CREATE TABLE public.loyalty_cards (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, token uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.loyalty_cards TO authenticated;
GRANT ALL ON public.loyalty_cards TO service_role;
ALTER TABLE public.loyalty_cards ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own loyalty card" ON public.loyalty_cards FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE TABLE public.store_loyalty_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.loyalty_cards(user_id), staff_id uuid NOT NULL REFERENCES public.profiles(id), receipt_reference text NOT NULL UNIQUE, articles_total numeric(12,2) NOT NULL, points_used integer NOT NULL DEFAULT 0, points_earned integer NOT NULL, request_id uuid NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.store_loyalty_transactions TO authenticated;
GRANT ALL ON public.store_loyalty_transactions TO service_role;
ALTER TABLE public.store_loyalty_transactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own or staff loyalty history" ON public.store_loyalty_transactions FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_staff_access(auth.uid()));
CREATE INDEX store_loyalty_user_idx ON public.store_loyalty_transactions(user_id,created_at DESC);
CREATE OR REPLACE FUNCTION public.normalize_loyalty_phone(_phone text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public,pg_temp AS $$ SELECT CASE WHEN digits ~ '^00212[67][0-9]{8}$' THEN substring(digits from 3) WHEN digits ~ '^0[67][0-9]{8}$' THEN '212'||substring(digits from 2) WHEN digits ~ '^212[67][0-9]{8}$' THEN digits ELSE NULL END FROM (SELECT regexp_replace(coalesce(_phone,''),'[^0-9]','','g') digits) p $$;
CREATE OR REPLACE FUNCTION public.loyalty_balance_for(_user uuid) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT (coalesce((SELECT sum(floor(greatest(subtotal-discount_amount-loyalty_discount,0)/10)) FROM public.orders WHERE user_id=_user AND status='delivered' AND created_at>='2026-11-24'::timestamptz),0)-coalesce((SELECT sum(loyalty_points_used) FROM public.orders WHERE user_id=_user AND status<>'cancelled'),0)+coalesce((SELECT sum(points_earned-points_used) FROM public.store_loyalty_transactions WHERE user_id=_user),0))::integer $$;
REVOKE ALL ON FUNCTION public.loyalty_balance_for(uuid) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.activate_my_loyalty_card() RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE t uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Connexion requise'; END IF; INSERT INTO public.loyalty_cards(user_id) VALUES(auth.uid()) ON CONFLICT(user_id) DO NOTHING; SELECT token INTO t FROM public.loyalty_cards WHERE user_id=auth.uid(); RETURN t; END $$;
REVOKE ALL ON FUNCTION public.activate_my_loyalty_card() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.activate_my_loyalty_card() TO authenticated;
CREATE OR REPLACE FUNCTION public.staff_find_loyalty_card(_query text) RETURNS TABLE(token uuid, customer_name text, phone text, balance integer) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE q text:=trim(coalesce(_query,'')); BEGIN IF auth.uid() IS NULL OR NOT public.has_staff_access(auth.uid()) THEN RAISE EXCEPTION 'Accès réservé au personnel'; END IF; IF q ~ '^MIMA:[0-9a-fA-F-]{36}$' THEN RETURN QUERY SELECT c.token,p.name,p.phone,greatest(public.loyalty_balance_for(c.user_id),0) FROM public.loyalty_cards c JOIN public.profiles p ON p.id=c.user_id WHERE c.token=substring(q from 6)::uuid; ELSIF public.normalize_loyalty_phone(q) IS NOT NULL THEN RETURN QUERY SELECT c.token,p.name,p.phone,greatest(public.loyalty_balance_for(c.user_id),0) FROM public.loyalty_cards c JOIN public.profiles p ON p.id=c.user_id WHERE public.normalize_loyalty_phone(p.phone)=public.normalize_loyalty_phone(q); ELSE RAISE EXCEPTION 'Scannez une carte Chez Mima ou saisissez un numéro mobile complet'; END IF; END $$;
REVOKE ALL ON FUNCTION public.staff_find_loyalty_card(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.staff_find_loyalty_card(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.staff_record_loyalty_sale(_token uuid,_receipt text,_articles_total numeric,_points_used integer,_request_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE u uuid; r text:=upper(trim(coalesce(_receipt,''))); earned integer; old public.store_loyalty_transactions%ROWTYPE; BEGIN IF auth.uid() IS NULL OR NOT public.has_staff_access(auth.uid()) THEN RAISE EXCEPTION 'Accès réservé au personnel'; END IF; SELECT user_id INTO u FROM public.loyalty_cards WHERE token=_token; IF u IS NULL THEN RAISE EXCEPTION 'Carte inconnue'; END IF; PERFORM pg_advisory_xact_lock(hashtext('promo:'||u::text)); SELECT * INTO old FROM public.store_loyalty_transactions WHERE request_id=_request_id; IF FOUND THEN IF old.user_id<>u OR old.receipt_reference<>r OR old.articles_total IS DISTINCT FROM _articles_total OR old.points_used IS DISTINCT FROM _points_used THEN RAISE EXCEPTION 'Cette opération a déjà été utilisée'; END IF; RETURN jsonb_build_object('balance',greatest(public.loyalty_balance_for(u),0),'earned',old.points_earned,'used',old.points_used); END IF; IF length(r)<3 OR length(r)>80 THEN RAISE EXCEPTION 'Référence du ticket obligatoire (3 à 80 caractères)'; END IF; IF _request_id IS NULL OR _articles_total IS NULL OR _articles_total::text IN ('NaN','Infinity','-Infinity') OR _articles_total<=0 OR _articles_total>100000 OR _articles_total<>round(_articles_total,2) THEN RAISE EXCEPTION 'Montant du ticket invalide'; END IF; IF _points_used IS NULL OR _points_used<0 OR _points_used%50<>0 THEN RAISE EXCEPTION 'Les points s''utilisent par paquets de 50'; END IF; IF _points_used>public.loyalty_balance_for(u) THEN RAISE EXCEPTION 'Solde de points insuffisant'; END IF; IF _points_used/5.0>=_articles_total THEN RAISE EXCEPTION 'La remise doit être inférieure au montant des articles'; END IF; IF EXISTS(SELECT 1 FROM public.store_loyalty_transactions WHERE receipt_reference=r) THEN RAISE EXCEPTION 'Ce ticket a déjà été enregistré'; END IF; earned:=floor((_articles_total-_points_used/5.0)/10)::integer; INSERT INTO public.store_loyalty_transactions(user_id,staff_id,receipt_reference,articles_total,points_used,points_earned,request_id) VALUES(u,auth.uid(),r,_articles_total,_points_used,earned,_request_id); RETURN jsonb_build_object('balance',greatest(public.loyalty_balance_for(u),0),'earned',earned,'used',_points_used); END $$;
REVOKE ALL ON FUNCTION public.staff_record_loyalty_sale(uuid,text,numeric,integer,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.staff_record_loyalty_sale(uuid,text,numeric,integer,uuid) TO authenticated;